sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var customerType = (current.getValue('customer_type') || '').toLowerCase().trim();
    var cg1 = (current.getValue('cg1') || '').toUpperCase().trim();

    // Strictly restrict execution to Non-Trade customers
    if (customerType !== 'non_trade' && cg1 !== 'N01') {
        return;
    }

    var segment = (current.getValue('segment') || '').toLowerCase().trim();
    if (!segment) {
        return;
    }

    var zone   = (current.getValue('zone') || '').trim();
    var region = (current.getValue('region') || '').trim();
    var depot  = (current.getValue('depot') || '').trim();

    var roleDefinitions = [];

    // Define strictly Non-Trade dynamic territory roles per segment
    if (segment === 'cement') {
        roleDefinitions.push(
            { role_name: 'NT CEMENT TSH', sequence_order: 10, min_amount: 0,       max_amount: 0,        number_of_days: '', level: 'depot' },
            { role_name: 'NT CEMENT RHM', sequence_order: 20, min_amount: 0,       max_amount: 2500000,  number_of_days: 30, level: 'region' },
            { role_name: 'NT CEMENT ZHM', sequence_order: 30, min_amount: 2500000, max_amount: 7500000,  number_of_days: 45, level: 'zone' },
            { role_name: 'NT CEMENT ZCH', sequence_order: 35, min_amount: 5000000, max_amount: 15000000, number_of_days: '', level: 'zone' }
        );
    } else if (segment === 'rmc') {
        roleDefinitions.push(
            { role_name: 'NT RMC TSM',   sequence_order: 10, min_amount: 0,       max_amount: 400000,  number_of_days: '', level: 'depot' },
            { role_name: 'NT RMC RH CH', sequence_order: 20, min_amount: 400000,  max_amount: 1100000, number_of_days: '', level: 'region' },
            { role_name: 'NT RMC ZCH',   sequence_order: 25, min_amount: 2500000, max_amount: 3200000, number_of_days: '', level: 'zone' },
            { role_name: 'NT RMC ZH',    sequence_order: 30, min_amount: 1100000, max_amount: 3200000, number_of_days: '', level: 'zone' }
        );
    } else if (segment === 'bpd') {
        roleDefinitions.push(
            { role_name: 'NT BPD TSH',    sequence_order: 10, min_amount: 0,       max_amount: 500000,  number_of_days: '', level: 'depot' },
            { role_name: 'NT BPD ZH BPD', sequence_order: 20, min_amount: 500000,  max_amount: 1000000, number_of_days: '', level: 'zone' },
            { role_name: 'NT BPD ZCH',    sequence_order: 40, min_amount: 2500000, max_amount: 3000000, number_of_days: '', level: 'zone' }
        );
    }

    // Process each required Non-Trade role configuration
    for (var i = 0; i < roleDefinitions.length; i++) {
        var def = roleDefinitions[i];

        var targetZone   = '';
        var targetRegion = '';
        var targetDepot  = '';

        // Determine geographic scope based on role level
        if (def.level === 'depot') {
            if (!depot) continue;
            targetZone   = zone;
            targetRegion = region;
            targetDepot  = depot;
        } else if (def.level === 'region') {
            if (!region) continue;
            targetZone   = zone;
            targetRegion = region;
            targetDepot  = '';
        } else if (def.level === 'zone') {
            if (!zone) continue;
            targetZone   = zone;
            targetRegion = '';
            targetDepot  = '';
        }

        // Check if approval matrix record already exists
        var checkMx = new GlideRecord('x_birl3_clm_approval_matrix');
        checkMx.addQuery('customer_type', 'non_trade');
        checkMx.addQuery('segment', segment);
        checkMx.addQuery('role_name', def.role_name);

        // Zone condition
        if (targetZone) {
            checkMx.addQuery('zone', targetZone);
        } else {
            checkMx.addNullQuery('zone').addOrCondition('zone', '');
        }

        // Region condition
        if (targetRegion) {
            checkMx.addQuery('region', targetRegion);
        } else {
            checkMx.addNullQuery('region').addOrCondition('region', '');
        }

        // Depot condition
        if (targetDepot) {
            checkMx.addQuery('depot', targetDepot);
        } else {
            checkMx.addNullQuery('depot').addOrCondition('depot', '');
        }

        checkMx.setLimit(1);
        checkMx.query();

        // If not found, insert with approver_user left blank
        if (!checkMx.hasNext()) {
            var newMx = new GlideRecord('x_birl3_clm_approval_matrix');
            newMx.initialize();

            newMx.setValue('customer_type', 'non_trade');
            newMx.setValue('segment', segment);
            newMx.setValue('role_name', def.role_name);
            newMx.setValue('sequence_order', def.sequence_order);
            newMx.setValue('min_amount', def.min_amount);
            newMx.setValue('max_amount', def.max_amount);
            newMx.setValue('number_of_days', def.number_of_days);
            newMx.setValue('pan_india', false);

            newMx.setValue('zone', targetZone);
            newMx.setValue('region', targetRegion);
            newMx.setValue('depot', targetDepot);

            newMx.setValue('approver_user', '');

            newMx.insert();
        }
    }

})(current, previous);
